  replace (x mod 2^64 + d + 2^31) with ((x + d + 2^31) + (-(x / 2^64) * 2^32) * 2^32) by lia.
  rewrite Z_mod_plus_full. rewrite Z.mod_small by lia. lia.
Qed.
